critic.suggestedFix:
Use parameterized queries with placeholders. Example fix:

export async function getUserById(db: DatabaseClient, userId: string): Promise<UserRecord | null> {
  const query = 'SELECT * FROM users WHERE id = $1';
  const result = await db.query(query, [userId]);
  return (result.rows[0] as UserRecord) ?? null;
}

Note: The exact placeholder syntax ($1, ?, %s) depends on the database driver used in DatabaseClient.
